 * Unit tests for ArrayUtils.add(T[] array, int index, T element)
 */
public class ArrayUtils_add_TriageGen5Test {











    @Test
    public void testAdd_NullArray_And_NullElement() {
        // Branch: array is null, element is null -> returns new Object[] { null }
        // Note: The method signature returns T[], but the logic returns Object[]
        Object[] result = ArrayUtils.add(null, 0, null);
        assertEquals(1, result.length);
        assertNull(result[0]);
