import org.apache.commons.lang3.builder.ToStringStyle;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for ArrayUtils.add(T[] array, int index, T element)
 */
public class ArrayUtils_add_TriageGen5Test {



















    @Test
    public void testAdd_PreservesComponentType() {
        // Ensure the returned array is of the correct component type
        Integer[] input = {1, 2};
        Integer[] result = ArrayUtils.add(input, 1, 15);
        assertTrue(java.lang.reflect.Array.newInstance(Integer.class, 3).getClass().isArray());
        assertEquals(Integer.class, result.getClass().getComponentType());
    }
}
